<?php
/** Native behavior test. Only a fresh, explicitly owned CLI database may run it. */
if ( PHP_SAPI !== 'cli' || ! defined( 'KIWE_DISCUSSION_NATIVE_TEST' ) || true !== KIWE_DISCUSSION_NATIVE_TEST || ! defined( 'KIWE_DISCUSSION_OWNED_DATABASE' ) || DB_NAME !== KIWE_DISCUSSION_OWNED_DATABASE || ! preg_match( '/^kiwe_cf23_[0-9]{8}_(store|editorial)$/D', DB_NAME ) ) throw new RuntimeException( 'Owned native discussion fixture required.' );

function kiwe_discussion_native_tests( bool $store ): array {
    global $wpdb;
    $checks = []; $GLOBALS['kiwe_discussion_test_checks'] =& $checks;
    $check = static function( $ok, string $label ) use ( &$checks ): void { $checks[$label] = (bool) $ok; if ( ! $ok ) throw new RuntimeException( $label ); };
    $code = static fn( $value ) => is_wp_error( $value ) ? $value->get_error_code() : '';
    $post = static fn( array $extra = [] ) => wp_insert_post( $extra + [ 'post_type'=>'post', 'post_status'=>'publish', 'post_title'=>'Native discussion fixture', 'post_content'=>'Synthetic public fixture.', 'comment_status'=>'open', 'post_author'=>1 ], true );
    $user = static function( string $label ): int { $id = wp_create_user( 'fixture_' . $label, wp_generate_password( 32 ), $label . '@example.test' ); if ( is_wp_error( $id ) ) throw new RuntimeException( 'Synthetic account unavailable' ); wp_update_user( [ 'ID'=>$id, 'display_name'=>$label ] ); return $id; };
    foreach ( [ 'comment_moderation'=>0,'comment_previously_approved'=>0,'comment_registration'=>0,'require_name_email'=>1,'thread_comments'=>1,'thread_comments_depth'=>3,'close_comments_for_old_posts'=>0,'comments_notify'=>0,'moderation_notify'=>0 ] as $key=>$value ) update_option( $key, (string) $value );
    $flood_clock = static fn() => false;
    add_filter( 'comment_flood_filter', $flood_clock, PHP_INT_MAX ); // Independent cases share a fixture clock; flood is tested separately below.
    add_filter( 'pre_comment_approved', [ DSA\Discussion\Discussion_Service::class, 'approval' ], PHP_INT_MAX, 2 );
    add_filter( 'get_comment_author', [ DSA\Discussion\Discussion_Service::class, 'author_name' ], 20, 3 );
    $_COOKIE[PK_VISITOR_COOKIE] = str_repeat( 'a', 32 );
    $service = new DSA\Discussion\Discussion_Service();
    $input = static fn( string $text, array $extra = [] ) => $extra + [ 'sendId'=>wp_generate_uuid4(), 'parent'=>0, 'name'=>'Chosen Reader', 'text'=>$text, 'email'=>'', 'rating'=>0 ];
    $reset_rate = static function() use ( $wpdb ): void { $wpdb->query( 'TRUNCATE TABLE ' . $wpdb->prefix . 'dsa_rate_limits' ); };
    $send = static function( int $id, string $text, array $extra = [] ) use ( $service,$input,$reset_rate ) { $reset_rate(); return $service->submit( $id, $input( $text, $extra ) ); };
    $reader = $user( 'reader' ); $unknown = $user( 'unknown' ); $proven = $user( 'proven' );
    pk_mark_factor_verified( $proven, 'email', 'proven@example.test' );
    $article = $post(); $other = $post( [ 'post_title'=>'Other fixture' ] );
    $check( ! is_wp_error( $article ) && ! is_wp_error( $other ), 'Native public content is available' );
    wp_set_current_user( 0 );
    $check( $service->composer( $article )['actor']['assurance'] === 'visitor', 'Guest composer does not borrow an account' );
    $check( is_wp_error( DSA\Discussion\Discussion_Target::get( $post( [ 'post_status'=>'private' ] ) ) ) && is_wp_error( DSA\Discussion\Discussion_Target::get( $post( [ 'post_password'=>'fixture-only' ] ) ) ), 'Private and password-protected targets stay unavailable to public reads' );
    wp_set_current_user( 1 );
    $hidden = $post( [ 'post_status'=>'draft' ] );
    $check( is_wp_error( DSA\Discussion\Discussion_Target::get( $hidden ) ), 'An owner session cannot export an unpublished discussion' );
    $check( DSA\Discussion\Public_Identity::clean( 'person@example.test' ) === '' && DSA\Discussion\Public_Identity::clean( '+91 98765 43210' ) === '', 'Contacts cannot be used as public discussion names' );
    wp_set_current_user( $reader );
    $check( DSA\Discussion\Public_Identity::current_name() === '', 'Generated account display-name local parts are not exposed' );
    $check( DSA\Discussion\Public_Identity::remember_current_name( "Asha O'Neil" ) && DSA\Discussion\Public_Identity::current_name() === "Asha O'Neil", 'Chosen public name uses the native profile owner' );
    unset( $_COOKIE[PK_VISITOR_COOKIE] );
    $check( $service->composer( $article )['deviceReady'], 'Signed-in composer works without a visitor-tracking cookie' );
    $draft = $input( "Unverified reader's comment \\ draft", [ 'name'=>"Asha O'Neil" ] );
    $first = $service->submit( $article, $draft );
    $check( ! is_wp_error( $first ) && $first['status'] === 'pending', 'An unverified subscriber is held for moderation' );
    $native = get_comment( $first['id'] );
    $check( $native->comment_content === $draft['text'] && $native->comment_author === "Asha O'Neil", 'Native slashing preserves apostrophes and literal backslashes' );
    $same = $service->submit( $article, $draft );
    $check( ! is_wp_error( $same ) && $same['repeated'] && $same['id'] === $first['id'], 'Exact Send retries return one native record' );
    $changed = $draft; $changed['text'] .= ' changed';
    $check( $code( $service->submit( $article, $changed ) ) === 'kiwe_discussion_changed', 'Reused Send identity cannot mutate an earlier draft' );
    $check( $service->listing( $article )['count'] === 0 && $service->listing( $article )['items'] === [], 'Pending text never appears in public lists or badge counts' );
    wp_set_current_user( $proven );
    $check( $service->composer( $article )['actor']['assurance'] === 'partial', 'One existing PhoneKey contact proof retains Partial assurance' );
    $batch=DSA\PhoneKey\PhoneKey_Bridge::verified_accounts([$reader,$unknown,$proven]);
    $check( !$batch[$reader] && !$batch[$unknown] && $batch[$proven], 'Batched PhoneKey proof projection matches existing native factor ownership' );
    $revoked=$user('revoked'); pk_upsert_factor($revoked,'email','verified','older'); pk_upsert_factor($revoked,'email','pending','newer');
    $batch=DSA\PhoneKey\PhoneKey_Bridge::verified_accounts([$revoked]);
    $check( !$batch[$revoked] && !pk_account_verified($revoked), 'Batched proof does not revive an older superseded factor' );
    $published = $send( $article, 'Verified reader native comment.' );
    $check( ! is_wp_error( $published ) && $published['status'] === 'published', 'A proven ordinary participant can publish under permissive native rules' );
    $incomplete=$input('A metadata failure must not leave half a published comment.');
    $before=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->comments} WHERE comment_post_ID=%d",$other));
    $deny_meta=static fn($value,$object,$key)=>$key==='_kiwe_discussion_body_v1'?false:$value;
    add_filter('add_comment_metadata',$deny_meta,PHP_INT_MAX,3); $reset_rate(); $failed=$service->submit($other,$incomplete); remove_filter('add_comment_metadata',$deny_meta,PHP_INT_MAX);
    $check( $code($failed)==='kiwe_discussion_unconfirmed' && (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->comments} WHERE comment_post_ID=%d",$other))===$before, 'Partial native metadata failure rolls back the comment and its provenance together' );
    $reset_rate(); $recovered=$service->submit($other,$incomplete);
    $check( !is_wp_error($recovered) && !$recovered['repeated'] && (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->comments} WHERE comment_post_ID=%d",$other))===$before+1, 'The same Send safely recovers after a rolled-back storage failure' );
    update_option( 'comment_moderation', '1' );
    $manual = $send( $article, 'Owner requires every comment to be reviewed.' );
    $check( ! is_wp_error( $manual ) && $manual['status'] === 'pending', 'Native manual approval still wins for a verified participant' );
    update_option( 'comment_moderation', '0' ); update_option( 'comment_previously_approved', '1' );
    $new_proven = $user( 'new_proven' ); pk_mark_factor_verified( $new_proven, 'email', 'new_proven@example.test' ); wp_set_current_user( $new_proven );
    $prior = $send( $article, 'Native prior-approval rule still applies.' );
    $check( ! is_wp_error( $prior ) && $prior['status'] === 'pending', 'Native previously-approved policy is not silently overridden' );
    update_option( 'comment_previously_approved', '0' ); wp_set_current_user( $proven );
    $spam_filter = static fn() => 'spam'; add_filter( 'pre_comment_approved', $spam_filter, 100 );
    $spam = $send( $article, 'Synthetic spam admission case.' ); remove_filter( 'pre_comment_approved', $spam_filter, 100 );
    $check( $code( $spam ) === 'kiwe_discussion_moderated' && (int) get_comments( [ 'post_id'=>$article, 'status'=>'spam', 'count'=>true ] ) === 1, 'Third-party spam admission is preserved without a false published receipt' );
    wp_set_current_user( 0 ); $_COOKIE[PK_VISITOR_COOKIE] = str_repeat( 'b', 32 );
    $claim_input = $input( 'Typed known email is not ownership proof.', [ 'email'=>'proven@example.test' ] ); $reset_rate();
    $claimed = $service->submit( $article, $claim_input );
    $check( ! is_wp_error( $claimed ) && $claimed['status'] === 'pending' && ! get_comment( $claimed['id'] )->user_id && ! get_current_user_id(), 'Matching an existing verified email grants neither session nor verification' );
    update_option( 'comment_registration', '1' );
    $login = $send( $article, 'Native members-only policy.', [ 'email'=>'new@example.test' ] );
    $check( $code( $login ) === 'not_logged_in', 'Native signed-in-only policy is enforced by WordPress' );
    update_option( 'comment_registration', '0' );
    $check( $code( $send( $article, 'No invented email for phone-only guest.' ) ) === 'require_name_email', 'Native required email is not bypassed with a fabricated contact' );
    wp_set_current_user( $proven );
    $reply = $send( $article, 'A native child reply.', [ 'parent'=>$published['id'] ] );
    $check( ! is_wp_error( $reply ) && get_comment( $reply['id'] )->comment_parent === (string) $published['id'], 'Replies use native parents on the same approved target' );
    $listing = $service->listing( $article );
    $check( $listing['count'] === 1 && $listing['items'][0]['replies'] === 1, 'Badge counts top-level approved comments and thread replies separately' );
    $check( $code( $send( $other, 'Cross-target reply.', [ 'parent'=>$published['id'] ] ) ) === 'kiwe_discussion_unavailable' && $code( $send( $article, 'Pending parent.', [ 'parent'=>$first['id'] ] ) ) === 'kiwe_discussion_unavailable', 'Cross-target and unpublished parents cannot be addressed' );
    $nested = $send( $article, 'Allowed nested reply.', [ 'parent'=>$reply['id'] ] );
    $check( ! is_wp_error( $nested ) && $code( $send( $article, 'Over-depth reply.', [ 'parent'=>$nested['id'] ] ) ) === 'kiwe_discussion_depth', 'Native thread-depth limits apply to the full parent chain' );
    wp_update_post( [ 'ID'=>$article, 'comment_status'=>'closed' ] );
    $check( $service->listing( $article )['count'] === 1 && $code( $send( $article, 'Closed write.' ) ) === 'kiwe_discussion_closed', 'Closing comments preserves approved reading and blocks new submissions' );
    wp_update_post( [ 'ID'=>$article, 'comment_status'=>'open' ] );
    wp_set_comment_status( $published['id'], 'hold' );
    $check( $service->listing( $article )['count'] === 0 && is_wp_error( $service->listing( $article, $reply['id'] ) ), 'Native moderation invalidates public counts and hides inaccessible thread ancestors' );
    $replay_after_moderation = $service->submit( $article, $claim_input );
    $check( $code($replay_after_moderation)==='kiwe_discussion_changed', 'An account change cannot reuse another private submission' );
    wp_set_comment_status( $published['id'], 'approve' );
    $page = $post( [ 'post_type'=>'page' ] );
    $check( DSA\Discussion\Discussion_Target::automatic_id( $page ) === 0, 'Site-wide comments are absent until an explicit native public page is selected' );
    update_option( DSA\Discussion\Discussion_Target::SITE_PAGE_OPTION, $page );
    $check( DSA\Discussion\Discussion_Target::automatic_id( $other ) === $other && DSA\Discussion\Discussion_Target::automatic_id( $page ) === $page, 'An explicit native site-feedback page does not replace contextual article discussion' );
    $query_target = $post( [ 'post_title'=>'Bounded pagination fixture' ] );
    for ( $i=0; $i<15; ++$i ) { $id = wp_insert_comment( [ 'comment_post_ID'=>$query_target, 'comment_author'=>'Public fixture reader', 'comment_author_email'=>'private@example.test', 'comment_content'=>'Public fixture ' . $i, 'comment_approved'=>1, 'comment_type'=>'comment', 'user_id'=>$proven ] ); wp_insert_comment( [ 'comment_post_ID'=>$query_target, 'comment_parent'=>$id, 'comment_author'=>'Reply reader', 'comment_content'=>'Child fixture', 'comment_approved'=>1 ] ); }
    $wpdb->queries = [];
    $chunk = $service->listing( $query_target ); $queries = $wpdb->queries;
    $next = $service->listing( $query_target, 0, $chunk['nextBefore'] );
    $check( count( $chunk['items'] ) === 12 && count( $next['items'] ) === 3 && $chunk['count'] === 15 && ! array_intersect( array_column( $chunk['items'], 'id' ), array_column( $next['items'], 'id' ) ), 'Bounded native cursor reaches every root without repeated items' );
    $aggregates = array_values( array_filter( $queries, static fn( $q ) => str_contains( $q[0], 'GROUP BY comment_parent' ) ) );
    $check( count( $aggregates ) === 1 && count( array_filter( array_column( $chunk['items'], 'replies' ), static fn( $n )=>$n===1 ) ) === 12, 'Visible reply counts use one bounded native aggregate' );
    $public = wp_json_encode( $chunk );
    $check( ! str_contains( $public, '@' ) && ! str_contains( $public, 'avatar' ) && ! str_contains( $public, 'user_id' ) && ! str_contains( $public, '192.0.2' ), 'Public projections contain no contact, avatar hash, account ID or IP address' );
    $flood = $send( $query_target, 'Exact native duplicate fixture.' );
    $duplicate = $send( $query_target, 'Exact native duplicate fixture.' );
    $check( ! is_wp_error( $flood ) && $code( $duplicate ) === 'comment_duplicate', 'Native duplicate admission still runs for a new Send identity' );
    remove_filter( 'comment_flood_filter', $flood_clock, PHP_INT_MAX );
    $flooded = $send( $query_target, 'Distinct content but too soon by the same actor.' );
    $check( $code( $flooded ) === 'comment_flood', 'Native flood protection remains effective' );
    add_filter( 'comment_flood_filter', $flood_clock, PHP_INT_MAX );
    $honeypot = $input( 'Synthetic bot', [ 'website'=>'https://bot.example.test' ] );
    $check( $code( $service->submit( $other, $honeypot ) ) === 'kiwe_discussion_input', 'Bot honeypot and strict mutation schema reject before native writes' );
    $reset_rate();
    for ( $i=0;$i<12;++$i ) $check( DSA\Utilities\Atomic_Rate_Limiter::allow( 'fixture-limit', 12, 600, false ), 'Atomic rate admission ' . ($i+1) );
    $check( ! DSA\Utilities\Atomic_Rate_Limiter::allow( 'fixture-limit', 12, 600, false ), 'Atomic rate limit refuses the next write' );
    $broken = static function( $sql ) use ( $wpdb ) { return str_starts_with( $sql, 'INSERT INTO ' . $wpdb->prefix . 'dsa_rate_limits' ) ? str_replace( 'bucket_hash', 'fixture_missing_column', $sql ) : $sql; };
    $wpdb->suppress_errors( true ); add_filter( 'query', $broken, PHP_INT_MAX );
    $check( ! DSA\Utilities\Atomic_Rate_Limiter::allow( 'broken-strict', 12, 600, false ) && DSA\Utilities\Atomic_Rate_Limiter::allow( 'legacy-open', 12, 600 ), 'Storage failure closes discussion admission while preserving existing limiter callers' );
    remove_filter( 'query', $broken, PHP_INT_MAX ); $wpdb->suppress_errors( false );
    $controller = new DSA\Rest\Discussion_Controller();
    $_SERVER['HTTP_ORIGIN']='https://outside.example.test'; $_SERVER['HTTP_SEC_FETCH_SITE']='cross-site';
    $r = new WP_REST_Request( 'POST' ); $r->set_header( 'X-Kiwe-Mutation', '1' ); $r->set_header( 'X-WP-Nonce', wp_create_nonce( 'wp_rest' ) );
    $check( !$controller->can_read() && is_wp_error( $controller->can_write( $r ) ), 'Cross-site read and mutation origins are rejected' );
    $_SERVER['HTTP_ORIGIN']=home_url(); $_SERVER['HTTP_SEC_FETCH_SITE']='same-origin';
    $r->set_header( 'X-WP-Nonce', 'stale' );
    $check( $code( $controller->can_write( $r ) ) === 'kiwe_discussion_nonce', 'Authenticated comment mutations require the current native REST nonce' );
    $r->set_header( 'X-WP-Nonce', wp_create_nonce( 'wp_rest' ) ); $check( true === $controller->can_write( $r ), 'Current native same-site mutation credentials are accepted' );
    if ( $store ) {
        $check( WC_VERSION === '11.2.1' && DSA\Apps\Store_App_Service::enabled(), 'Actual WooCommerce 11.2.1 owns product review behavior' );
        update_option( 'woocommerce_enable_reviews','yes' ); update_option( 'woocommerce_enable_review_rating','yes' ); update_option( 'woocommerce_review_rating_required','yes' ); update_option( 'woocommerce_review_rating_verification_required','no' );
        $product = new WC_Product_Simple(); $product->set_name('Synthetic review product'); $product->set_status('publish'); $product->set_regular_price('10'); $product->set_reviews_allowed(true); $pid = $product->save();
        $check( $code( $send( $pid, 'Missing stars.' ) ) === 'kiwe_review_rating', 'Store required-star policy is checked without invoking a fatal Woo form response' );
        $review = $send( $pid, 'A real native five star fixture.', [ 'rating'=>5 ] );
        $check( !is_wp_error($review) && get_comment($review['id'])->comment_type==='review' && (int)get_comment_meta($review['id'],'rating',true)===5 && (int)wc_get_product($pid)->get_rating_count()===1, 'Native review type, star metadata and Woo aggregate are preserved' );
        $review_reply = $send( $pid, 'Review child does not add stars.', [ 'parent'=>$review['id'] ] );
        $check( !is_wp_error($review_reply) && get_comment_meta($review_reply['id'],'rating',true)==='' && (int)wc_get_product($pid)->get_rating_count()===1, 'Review replies do not alter the product rating aggregate' );
        $check( $code($send($pid,'No duplicate reply stars.',['parent'=>$review['id'],'rating'=>4]))==='kiwe_review_reply_rating', 'A reply cannot create a second rating' );
        update_option('woocommerce_review_rating_verification_required','yes');
        $check( $code($send($pid,'Not a proven buyer.',['rating'=>4]))==='kiwe_review_buyer_required', 'Woo buyer-only policy cannot be bypassed with an authenticated nonbuyer' );
        $order=wc_create_order(['customer_id'=>$proven]); $order->set_billing_email('proven@example.test'); $order->add_product($product,1); $order->set_status('completed'); $order->save();
        $check( DSA\Commerce\Discussion_Review_Adapter::current_buyer($pid), 'Native completed purchase is resolved only for the proven current account' );
        wp_set_current_user(0); $_COOKIE[PK_VISITOR_COOKIE]=str_repeat('c',32);
        $check( $code($send($pid,'Claimed buyer email.',['rating'=>5,'email'=>'proven@example.test']))==='kiwe_review_buyer_required', 'Typing a buyer email cannot claim its purchase or verified-owner permission' );
        wp_set_current_user($proven); update_option('woocommerce_review_rating_verification_required','no');
        update_option('woocommerce_enable_reviews','no'); remove_post_type_support('product','comments');
        $closed=$service->listing($pid);
        $check( !is_wp_error($closed) && $closed['count']===1 && !$closed['target']['open'] && in_array($code($send($pid,'Closed product review.',['rating'=>3])),['kiwe_review_closed','kiwe_discussion_closed'],true), 'Disabling new product reviews preserves approved review history' );
    } else {
        $check( !function_exists('WC') && !class_exists('DSA\\Commerce\\Discussion_Review_Adapter',false), 'Editorial discussion never loads Woo or its Store review adapter' );
        register_post_type('product',['public'=>true,'supports'=>['title','comments']]); $pid=$post(['post_type'=>'product']);
        $check( is_wp_error(DSA\Discussion\Discussion_Target::get($pid)) && !class_exists('DSA\\Commerce\\Discussion_Review_Adapter',false), 'Unavailable Store content cannot activate its adapter through a public target ID' );
    }
    require_once __DIR__ . '/test-wordpress-discussion-composer.php';
    kiwe_discussion_composer_tests($check);
    require_once __DIR__ . '/test-wordpress-discussion-identity-matrix.php';
    kiwe_discussion_identity_matrix_tests($check);
    require_once __DIR__ . '/test-wordpress-discussion-reactions.php';
    kiwe_discussion_reaction_tests($check);
    require_once __DIR__ . '/test-wordpress-discussion-feedback.php';
    kiwe_discussion_feedback_tests($check,$store);
    require_once __DIR__ . '/test-wordpress-discussion-boundaries.php';
    kiwe_discussion_boundary_tests($check,$store);
    require_once __DIR__ . '/test-wordpress-discussion-query-cost.php';
    kiwe_discussion_query_cost_tests($check);
    update_option('cf23_concurrency_fixture',['post'=>$post(['post_title'=>'Concurrent native Send']), 'user'=>$proven,'send'=>wp_generate_uuid4()]);
    $reset_rate();
    return [ 'passed'=>true,'checks'=>$checks,'wordpress'=>$GLOBALS['wp_version'],'woo'=>$store?WC_VERSION:null,'nativeStorage'=>true,'fixture'=>'Fresh synthetic database; owned runner drops it after receipt.','peakBytes'=>memory_get_peak_usage(true),'queryCost'=>$GLOBALS['kiwe_discussion_query_cost']??null ];
}
